def solution(phone_book):
    phone_set = set(phone_book)
    for phone in phone_set:
        for i in range(len(phone)):
            prefix = phone[:i]
            # in 연산자는 list에서 평균 O(n)인 반면, set에서 평균 O(1) 최악 O(n)이 걸린다.
            if prefix in phone_set:
                return False
    return True



phone_book = ["97674223", "567567567567567567567567567567567567567567567567567567567567567", "9767422397674223976742239767422397674223976742239767422397674223","","567567567567567567567567567567567567567567567567567567567567567","88"]
print(solution(phone_book))
